// PassCost is the rows a request would add to a pass now: every question's
// branch, plus its state unless the prefix cache holds it. It is what a
// scheduler orders requests by (K9); a pass's time grows with its rows.
func (g *GPU) PassCost(enc *Encoding) int {
	n := enc.StateLen
	if g.cache.peek(enc.IDs[:enc.StateLen]) >= 0 {
		n = 0
	}
	for k := range enc.Decide {
		lo, hi := enc.Branch(k)
		n += hi - lo
	}
	return n
}

// FitsOnePass is whether ForwardBatch would answer these requests as one pass
// with the prefix cache as it is now: rows, attention cells and state slots.
func (g *GPU) FitsOnePass(encs []*Encoding) bool {
	resident := make([]bool, len(encs))
	for i, enc := range encs {
		resident[i] = g.cache.peek(enc.IDs[:enc.StateLen]) >= 0
	}
	_, ok := g.planBatch(encs, resident)
	return ok
}

