			waiting[i].cost = b.gpu.PassCost(waiting[i].job.enc)
		}
		pick := pickKev(waiting, time.Now(), b.opt.MaxBatch, b.opt.BatchTokens, kevMaxWait,
			func(idx []int) bool {
				encs := make([]*kev.Encoding, len(idx))
				for i, k := range idx {
					encs[i] = waiting[k].job.enc
				}
				return b.gpu.FitsOnePass(encs)
			})
		batch := make([]kevJob, len(pick))
		taken := make([]bool, len(waiting))
		for i, k := range pick {
			batch[i], taken[k] = waiting[k].job, true
		}
		rest := waiting[:0]
		for k, w := range waiting {
