// kevMaxWait is how long a request may be passed over for cheaper ones
// before it goes first, so a long text is not starved by a stream of short
// ones.
const kevMaxWait = time.Second

// kevWaiting is a queued request, when it arrived, and its pass cost in rows.
type kevWaiting struct {
	job   kevJob
	since time.Time
	cost  int
}

// pickKev chooses the next pass from the waiting requests and returns their
// indices. The first is the oldest request if it has waited maxWait, else the
// cheapest (the oldest among equals); it runs even alone and over budget.
// Then the others join, cheapest first, while the pass stays within maxN
// requests and budget rows and fits (one pass, as ForwardBatch plans it).
// A request that does not fit is skipped, not the end of the search.
func pickKev(w []kevWaiting, now time.Time, maxN, budget int, maxWait time.Duration, fits func([]int) bool) []int {
	order := make([]int, len(w))
	for i := range order {
		order[i] = i
	}
	sort.SliceStable(order, func(a, b int) bool { return w[order[a]].cost < w[order[b]].cost })
	head := order[0]
	oldest := 0
	for i := range w {
		if w[i].since.Before(w[oldest].since) {
			oldest = i
		}
	}
	if now.Sub(w[oldest].since) >= maxWait {
		head = oldest
	}
	pick, rows := []int{head}, w[head].cost
	for _, k := range order {
		if len(pick) >= maxN {
			break
		}
		if k == head || rows+w[k].cost > budget {
			continue
		}
		if !fits(append(pick[:len(pick):len(pick)], k)) {
			continue
		}
		pick, rows = append(pick, k), rows+w[k].cost
	}
	return pick
}

