package backend

import (
	"slices"
	"testing"
	"time"
)

// TestPickKev is K9's scheduler on its own: costs in rows, arrival times,
// and a fit that stands in for the planner.
func TestPickKev(t *testing.T) {
	t0 := time.Unix(0, 0)
	wait := func(costs ...int) []kevWaiting {
		w := make([]kevWaiting, len(costs))
		for i, c := range costs {
			w[i] = kevWaiting{since: t0.Add(time.Duration(i) * time.Millisecond), cost: c}
		}
		return w
	}
	all := func([]int) bool { return true }
	now := t0.Add(100 * time.Millisecond)
	cases := []struct {
		name string
		w    []kevWaiting
		now  time.Time
		fits func([]int) bool
		want []int
	}{
		{"one", wait(100), now, all, []int{0}},
		{"shorts share, cheapest first", wait(120, 100, 110), now, all, []int{1, 2, 0}},
		{"a long text waits for the shorts", wait(2300, 100, 100), now, all, []int{1, 2}},
		{"a long text alone runs over budget", wait(2300), now, all, []int{0}},
		{"the budget", wait(400, 400, 400), now, all, []int{0, 1}},
		{"the batch size", wait(10, 10, 10, 10, 10, 10, 10, 10, 10), now, all, []int{0, 1, 2, 3, 4, 5, 6, 7}},
