cat > kev/zz_overhead_test.go <<'EOF'
package kev

import (
	"testing"
	"time"
)

// Temporary (K9 measurement): where a short request's wall time goes.
func TestZZOverhead(t *testing.T) {
	g := loadGPU(t)
	e := loadEncoder(t)
	raw := loadFixtures(t)[0].Request
	var parse, encode, plan, upload, runWall, runGPU, read, head, save, total time.Duration
	const n = 20
	for i := 0; i < n+3; i++ {
		g.ClearCache()
		t0 := time.Now()
		req, _ := ParseRequest(raw)
		rec, _ := ToRecord(req)
		t1 := time.Now()
		enc, err := e.Encode(rec, MaxState, MaxRow)
		if err != nil {
			t.Fatal(err)
		}
		t2 := time.Now()
		ps, _ := g.plan(enc, false)
		p := ps[0]
		t3 := time.Now()
		if err := g.upload(p); err != nil {
			t.Fatal(err)
		}
		t4 := time.Now()
		// run without its upload
		per := max(g.LayersPerSubmit, 1)
		var gpu time.Duration
		for l := 0; l < len(g.w); l += per {
			var d []vkMD
			for j := l; j < min(l+per, len(g.w)); j++ {
				dj, _ := g.layerGraph(j, p)
				d = append(d, dj...)
			}
			dur, err := dispatchTimed(d)
			if err != nil {
				t.Fatal(err)
			}
			gpu += dur
		}
		t5 := time.Now()
		out := &Pass{Hidden: map[int][]float32{}}
		g.readRows(p, p.readouts, true, []map[int][]float32{out.Hidden})
		t6 := time.Now()
		g.headProbs(enc, out)
		t7 := time.Now()
		g.cache.save(g, enc.IDs[:enc.StateLen], 0, 0)
		t8 := time.Now()
		if i < 3 {
			continue
		}
		parse += t1.Sub(t0); encode += t2.Sub(t1); plan += t3.Sub(t2); upload += t4.Sub(t3)
		runWall += t5.Sub(t4); runGPU += gpu; read += t6.Sub(t5); head += t7.Sub(t6); save += t8.Sub(t7); total += t8.Sub(t0)
	}
	ms := func(d time.Duration) float64 { return float64(d.Microseconds()) / 1000 / n }
	t.Logf("parse %.2f encode %.2f plan %.2f upload %.2f run wall %.2f (gpu %.2f) readback %.2f head %.2f cache save %.2f | total %.2f ms",
		ms(parse), ms(encode), ms(plan), ms(upload), ms(runWall), ms(runGPU), ms(read), ms(head), ms(save), ms(total))
}
EOF
