#version 450
#extension GL_KHR_shader_subgroup_basic : require
#extension GL_KHR_shader_subgroup_clustered : require
#extension GL_KHR_shader_subgroup_arithmetic : require
#extension GL_EXT_control_flow_attributes : require

#include "dit_common.glsl"

#define CH 8192u
#define QK 2048u
#define NV 32u
#define WG 256u

layout(local_size_x = 256) in;

shared float conv[CH];
shared float inv[32];

float silu(float x) { return x / (1.0 + exp(-x)); }

float softplus(float x) { return x > 20.0 ? x : log(1.0 + exp(x)); }

// row of P holding the input `back` tokens before token r (back >= 1), or -1
// for a zero, or -2 - i for row i of the cached tail.
