		b.batches++
		b.batched += len(batch)
	}
	for i, j := range batch {
		j.done <- kevResult{probs: probs[i], ms: ms}
	}
	if sp != nil {
		b.stream = nil
		b.batches++
		b.batched++
		st.job.done <- kevResult{probs: sp, ms: st.ms}
	}
}

